INSERT INTO public.avatars (id, user_id, config, created_at) VALUES ('7481e9dc-b2de-4aad-9896-f3dbe47ef613', '8234fac7-a641-484c-8e8b-b8ffc6d5dfaa', '{"topi": "none", "hijab": "pashmina", "kulit": "#eec39a", "tubuh": "sedang", "wajah": "oval", "atasan": "blouse", "sepatu": "loafers", "bawahan": "celana-panjang", "kacamata": false, "hijabWarna": "#5c4033", "itemTangan": "buku", "atasanWarna": "#2f2a3c", "rambutModel": "cepol", "rambutWarna": "#4a2c14", "sepatuWarna": "#17130f", "bawahanWarna": "#26232e"}', '2026-10-20 17:35:43.747149+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('1c706eae-0c9c-46d9-99d9-a0fc06e0ec18', 'bc7007b7-8560-4eb8-8a75-0f3ba3db3eb5', 'Dari Nol Jadi Berani', 'Kita masuk PPG cuma modal nekat dan doa. Sekarang lihat: kita bisa berdiri di depan kelas, menjelaskan fungsi kuadrat tanpa gemetar. Terima kasih sudah saling menguatkan saat tugas menumpuk dan air mata hampir jatuh. Kita berhasil, dan ini baru awal.', 'semangat', 'SMPN 2 Salatiga', 2, '2026-10-20 17:35:43.668384+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('db70810c-ea7c-4cbb-a279-ad00e9417c03', 'f9b394f6-65ca-4a29-8372-fa37996ad35f', 'Untuk Keluarga Matematikaku', 'Dulu aku pikir matematika itu cuma angka. Ternyata di PPG aku belajar yang paling sulit dihitung: kadar sayang pada orang-orang yang baru sembilan bulan dikenal. Terima kasih sudah jadi keluarga. Sampai jumpa di ruang guru masing-masing, ya.', 'haru', 'SMPN 2 Salatiga', 2, '2026-10-20 17:35:43.671443+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('0bef6296-29f5-42d9-911c-354be645349a', '33c171cd-d973-476d-9e19-abaec6901fca', 'Memoar Anak Kost Dekat Kampus', 'Terima kasih untuk yang selalu bangunin aku pas hampir telat microteaching, yang rela berbagi indomie jam 11 malam, dan yang pura-pura paham pas aku presentasi. Semoga rezeki kalian lancar seperti integral parsial yang ketemu polinom.', 'lucu', 'SMPN 2 Salatiga', 2, '2026-10-20 17:35:43.674575+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('747e6c96-6c7b-4c98-9a82-4294c792d933', '48ff639f-7afa-42a8-a51d-75f1f851b76f', 'Sempurna pada Waktunya', 'Setiap kali merasa gagal saat PPL, ada saja yang bilang: gapapa, coba lagi besok. Kalimat sederhana itu yang bikin aku bertahan sampai hari ini. Semoga Tuhan membalas kebaikan kalian berlipat-lipat. Kita berpisah bukan untuk melupakan, tapi untuk membuktikan.', 'syukur', 'SMPN 2 Salatiga', 2, '2026-10-20 17:35:43.677091+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('ee8f8cc5-66f2-4fdf-a49e-093d48e45824', 'f9e1f05f-1011-4692-b27f-6ccbc731bba7', 'Titik Temu Kita', 'Dari 29 latar belakang yang berbeda, kita menemukan titik temu yang sama: ingin jadi guru yang baik. Perjalanan dari Februari sampai Oktober ini melelahkan, tapi kalau diulang dari awal, aku tetap mau. Asalkan bareng kalian lagi.', 'haru', 'SMPN 2 Salatiga', 2, '2026-10-20 17:35:43.679437+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('7d28b9f6-0245-43c2-a3b0-18085dd01830', 'a0aa915a-1e13-4684-99fa-aeee820aebd9', 'Rumus Bahagia', 'Kalau bahagia itu fungsi, maka variabelnya adalah waktu bersama kalian. Terima kasih untuk setiap diskusi yang berakhir tertawa, setiap remedial kehidupan yang kita jalani bareng. Jangan lupa: guru hebat lahir dari hati yang mau belajar terus.', 'inspiratif', 'SMPN 2 Salatiga', 2, '2026-10-20 17:35:43.681667+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('64632511-3b43-46d2-8360-aa388ecfb1a0', 'e22f1cb5-5e57-442b-9d21-4c39b31d5d90', 'Sampai Ketemu di Puncak', 'Kita pernah sama-sama nggak tidur karena revisi RPP. Sekarang saatnya kita sama-sama tidak tidur karena menyiapkan masa depan anak-anak Indonesia. Semangat terus, guruku. Kalau lelah, ingat Salatiga, ingat kita, ingat bahwa kamu tidak pernah sendirian.', 'semangat', 'SMAN 1 Salatiga', 2, '2026-10-20 17:35:43.683883+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('1b301283-5216-455b-929a-dcfa92d6a9f6', 'b82bc1cb-319e-48d9-8fb2-53b79a799080', 'Peluk Jarak Jauh', 'Buat kalian yang baca ini sambil senyum: iya, aku kangen duluan. Kangen ributnya grup chat, kangen piket bareng, kangen semua. Semoga kelak anak murid kalian tahu, gurunya pernah jadi orang paling hangat di Salatiga.', 'kasih', 'SMAN 1 Salatiga', 2, '2026-10-20 17:35:43.686075+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('dc74286a-96ac-4c2f-ba4d-2b2d3457a980', '125510ca-90f6-43fe-a47c-8725b89fa828', 'Bukti Otentik', 'Pernyataan: 29 orang asing bisa jadi keluarga dalam 9 bulan. Bukti: kita. Kesimpulan: matematika tidak pernah salah, perasaan juga tidak. Terima kasih sudah jadi jawaban dari soal yang tidak pernah selesai: ''nanti kangen siapa ya pas lulus?''', 'lucu', 'SMAN 1 Salatiga', 2, '2026-10-20 17:35:43.688364+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('8394f747-4eab-4ddf-a18b-7e1d6261a55e', 'e44be97a-8bbc-4116-879d-cdcc5187d1cb', 'Selasar E yang Kita Lewati', 'Masih ingat lorong waktu kita nunggu giliran microteaching? Deg-degannya, doanya, saling lempar semangatnya. Sekarang lorong itu cuma kenangan, tapi aku bawa semua suaranya dalam hati. Terima kasih, teman seperjalanan. Kalian luar biasa.', 'haru', 'SMAN 1 Salatiga', 2, '2026-10-20 17:35:43.690707+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('ad919467-576c-4749-b0fd-47a28c3e9314', '5f542d72-f8d2-46ea-a0e1-51f9e10b4133', 'Hutang Budi pada Kalian', 'Aku pernah hampir menyerah di tengah jalan. Kalian yang menarikku kembali dengan cara yang sederhana: mengajak makan, mendengarkan, mengingatkan mimpi awal. Hutang budiku pada kalian tidak bisa dihitung dengan notasi sigma. Terima kasih banyak.', 'syukur', 'SMAN 1 Salatiga', 2, '2026-10-20 17:35:43.692926+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('d97d7764-e101-4365-8397-6480acfd9d5b', 'e422a1d7-d426-472b-87f9-363d7bea987e', 'Garis Singgung', 'Hidup kita seperti garis singgung lingkaran: bertemu di satu titik bernama Salatiga, lalu melaju ke arah masing-masing. Tapi titik itu mengubah lintasan kita selamanya. Teruslah melaju, temanku. Sampai jumpa di titik-titik berikutnya.', 'semangat', 'SMAN 1 Salatiga', 2, '2026-10-20 17:35:43.695122+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('93e21b71-f124-471d-8265-4978c4727670', '0a353120-b1f4-45de-b401-97ec6797547e', 'Kita Adalah Bukti', 'Kata orang, jadi guru itu pengabdian tanpa ujung. Setelah PPG, aku percaya itu bukan beban, melainkan kehormatan. Kita sudah membuktikan bahwa kita mampu. Sekarang tinggal membuktikan bahwa kita konsisten. Ayo tunjukkan pada dunia.', 'inspiratif', 'SMAN 2 Salatiga', 2, '2026-10-20 17:35:43.697262+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('d84afdc1-9847-477d-a8fb-6096a6a1bc78', 'd20afcba-f464-4c81-a9c0-64dbef21eea4', 'Surat Kecil dari Maya', 'Aku tidak pandai berkata-kata saat pamit langsung, jadi kutulis di sini. Kalian adalah alasan Salatiga terasa seperti rumah. Setiap sudut kampus punya cerita tentang kita. Jaga kesehatan, jaga mimpi, jaga persahabatan ini. Aku sayang kalian semua.', 'haru', 'SMAN 2 Salatiga', 2, '2026-10-20 17:35:43.699365+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('0f016b1b-7325-4472-ae76-2bc3adfddc20', '8fdc6f0c-a195-4a1f-bfae-d4c33becc10b', 'Daftar Hadir Kebaikan', 'Hadir: yang minjemin catatan. Hadir: yang beliin kopi pas begadang. Hadir: yang bohong bilang ''nggak gendut kok''. Hadir: semua orang baik di PPG Matematika ini. Tidak ada yang alpha. Kalian semua lulus jadi manusia baik.', 'lucu', 'SMAN 2 Salatiga', 2, '2026-10-20 17:35:43.701573+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('653608e8-9166-493d-b3dc-ec9f6526ca04', '0c48bd48-827b-4ee6-aa44-67f3ebafaa18', 'Akar dan Sayap', 'Ada yang bilang, beri orang yang kamu sayangi dua hal: akar dan sayap. Kalian memberiku keduanya. Akar berupa persahabatan yang menenangkan, sayap berupa keberanian untuk terbang jadi guru. Terima kasih banyak-banyak. Sampai jumpa lagi.', 'kasih', 'SMAN 2 Salatiga', 2, '2026-10-20 17:35:43.703697+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('d38a57b9-59fe-4e01-87b9-85d96cefcea7', '338e6fe8-18b6-4c2a-aced-fe84dd39652f', 'Syiukur yang Tak Habis', 'Ya, aku sengaja salah tulis, biar kalian ketawa. Itulah kita: selalu menemukan alasan untuk tertawa bahkan di minggu paling berat. Terima kasih sudah mengajariku bahwa jadi guru tidak harus selalu serius. Kadang jadi manusia yang hadir saja sudah cukup.', 'syukur', 'SMAN 2 Salatiga', 2, '2026-10-20 17:35:43.705797+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('501daac9-c006-425a-83de-7e9cee663642', '378009a4-8f40-4cb7-8f43-92bc68eef8cd', 'Deret Tak Hingga', 'Kebaikan kalian padaku seperti deret geometri dengan rasio lebih dari satu: membesar tanpa henti, tanpa kesudahan. Semoga hidup kalian konvergen menuju bahagia. Dan semoga kelak, kita berkumpul lagi menceritakan murid-murid hebat kita.', 'inspiratif', 'SMAN 2 Salatiga', 2, '2026-10-20 17:35:43.707967+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('632a0863-f35f-45c4-b4e8-9f730165840d', '1650864f-5f9c-4454-ac87-38ac1daa3b9c', 'Hal Terakhir yang Kukatakan', 'Kalau ditanya apa yang paling berat dari lulus, jawabannya bukan skripsi, bukan ujian — tapi berpisah dengan kalian. Terima kasih sudah jadi tempat pulang selama sembilan bulan ini. Semoga setiap langkah kita diberkahi.', 'haru', 'SMAN 3 Salatiga', 2, '2026-10-20 17:35:43.710423+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('a512f4d7-148a-4df4-9dad-1465333c0a87', '5a39d2a0-f3fc-4fbf-8130-42bbaa8952c3', 'Jangan Padam', 'Kita sudah melewati Februari yang canggung, Maret yang melelahkan, Juli yang menegangkan, dan Oktober yang mengharukan. Api semangat kita sudah teruji. Jadi tolong, di manapun kalian bertugas nanti: jangan biarkan api itu padam.', 'semangat', 'SMAN 3 Salatiga', 2, '2026-10-20 17:35:43.713072+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('81d598ec-1cfe-4f45-8bdb-fd45c4d8a3ab', '0cf084ed-7966-47fd-b13b-d41c7e7e9de5', 'Kotak Kenangan', 'Kalau kenangan bisa dikotakkan, kotakku penuh: tawa di kantin, panik bareng sebelum microteaching, terharu pas PPL perpisahan sama murid-murid. Isinya semua tentang kalian. Kusimpan rapat, kubawa jauh. Terima kasih sudah mengisinya.', 'kasih', 'SMAN 3 Salatiga', 2, '2026-10-20 17:35:43.71545+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('11bfacc7-29be-4e39-bca7-a7547efa15f5', '9d1cbf44-759a-412e-bcdf-14b8372f02d3', 'Logika Matematika Cinta', 'Jika A sayang B, dan B sayang C, belum tentu A sayang C. Tapi di PPG ini terbukti salah: kita semua saling sayang tanpa perlu pembuktian induksi. Terima kasih untuk 270 harinya. Jangan lupa balik modal ya, eh, balik kangen maksudnya.', 'lucu', 'SMAN 3 Salatiga', 2, '2026-10-20 17:35:43.717745+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('45461319-4171-40a8-9bd6-d505e8789b4f', '75715e6a-664f-426c-ae71-819eca23af4e', 'Rencana yang Indah', 'Dulu aku mendaftar PPG karena coba-coba. Sekarang aku pulang membawa mimpi besar dan 28 saudara baru. Rencana Tuhan memang selalu lebih indah dari rencana kita. Terima kasih untuk setiap doa yang diam-diam kalian kirimkan untukku.', 'syukur', 'SMAN 3 Salatiga', 2, '2026-10-20 17:35:43.72017+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('b5d03472-11a4-4486-9770-7343e2e1be20', 'c2e0e2ed-f424-45ac-aed3-12e2bf5822b7', 'Transformasi', 'Dalam geometri, transformasi mengubah posisi tanpa menghilangkan identitas. Begitu pula kita: berpindah ke kota-kota baru, tapi tidak akan pernah kehilangan jati diri sebagai keluarga PPG Matematika 2026. Sampai jumpa di koordinat kebahagiaan masing-masing.', 'inspiratif', 'SMAN 3 Salatiga', 2, '2026-10-20 17:35:43.722488+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('e2188605-73f3-4345-b375-7d983af01d71', '77cdf1b6-6a7f-4a81-88a9-89430212a121', 'Terima Kasih, Guru-Guruku', 'Sebelum jadi guru sungguhan, izinkan aku memanggil kalian semua guruku. Guru tentang kesabaran, tentang kekuatan, tentang terus berusaha walau hasil belum terlihat. Semoga kelak kita bertemu dalam keadaan sudah mengubah banyak hidup.', 'haru', 'SMKN 1 Salatiga', 2, '2026-10-20 17:35:43.724688+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('719df7e1-bad1-452e-a970-3367012f0c12', 'bb7bd5ad-88ef-49e3-b44a-7f21121219f8', 'Satu Frekuensi', 'Sembilan bulan cukup untuk memahami bahwa kita ini satu frekuensi: sama-sama pusing dengan asesmen, sama-sama bahagia saat murid bilang ''oh gitu caranya'', sama-sama ingin Indonesia lebih baik. Bawa frekuensi ini ke sekolah kalian. Aku tunggu kabar baiknya.', 'semangat', 'SMKN 1 Salatiga', 2, '2026-10-20 17:35:43.726831+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('23d49a7d-f85c-4e65-9917-7b0778b214c7', '8de5df6b-8969-400d-be47-22eef61e69ee', 'Bilangan Prima Kita', 'Kita ini seperti bilangan prima: unik, tidak bisa dipecah sembarangan, dan istimewa dengan caranya masing-masing. Terima kasih sudah menerimaku apa adanya. Semoga kita semua selalu dikelilingi orang-orang yang menghargai keunikan kita.', 'kasih', 'SMKN 1 Salatiga', 2, '2026-10-20 17:35:43.729147+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('33290dac-39fe-4d44-900a-575500c3bff5', '8ff06552-b953-414b-b79a-ce072c4e5189', 'Hasil Observasi Lapangan', 'Setelah mengobservasi 29 spesimen manusia selama 9 bulan, kudapatkan data: 100% baik hati, 90% hobi ngantuk di kelas pagi, 100% calon guru hebat. Kesimpulan: angkatan kita tidak perlu direvisi. Saran: jangan berubah, tetap jadi orang baik.', 'lucu', 'SMKN 1 Salatiga', 2, '2026-10-20 17:35:43.731376+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('d013981e-b93e-4dc4-935c-aa57b763322f', '640ae0f2-75da-4fee-83c4-1b8f137b1b0b', 'Satu-Satunya yang Bilang Iya', 'Jadi satu-satunya laki-laki di angkatan ini mengajariku banyak hal: tentang mendengar, tentang menghormati, tentang ketulusan 28 kakak-adik yang luar biasa. Terima kasih sudah menerimaku. Suatu hari, murid-murid kalian akan bangga punya guru seperti kalian. Salam hangat dari admin kalian.', 'syukur', 'SMKN 1 Salatiga', 2, '2026-10-20 17:35:43.733896+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('2d28c02d-2c68-4c54-9d86-6877ebf61828', 'dc66c0a9-d9e4-4b20-868b-6e90cda8452f', 'Guru Adalah Perjalanan', 'Anak-anakku, mengajar matematika bukan sekadar menuliskan rumus di papan. Ia adalah cara kita menabur keberanian berpikir. Bawa integritas yang kalian pelajari di sini ke setiap kelas. Kami akan selalu bangga. — Pak Budi', 'inspiratif', 'e107', 2, '2026-10-20 17:35:43.736441+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('52aa5917-d966-4d8e-987e-86776cff8841', 'fb0b2557-53cc-44fa-b1f0-448691a30adb', 'Ruang E108 Akan Selalu Ada', 'Kalian datang sebagai mahasiswa, pergi sebagai guru. Ruang kelas ini akan sepi setelah kalian lulus, tapi pintunya tidak pernah tertutup. Kembalilah kapan saja, ceritakan murid-muridmu. Kami menunggu kabar baik. — Bu Sari', 'haru', 'e108', 2, '2026-10-20 17:35:43.738805+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('2427c108-ed34-4a2f-8428-bd5799de8845', '194cc71e-9df4-4f69-8f8d-66fc3d10a93b', 'Buktikan!', 'Dunia pendidikan menanti gagasan segar kalian. Jangan takut berbeda, jangan takut mencoba. Matematika mengajarkan ketelitian; kehidupan menuntut keberanian. Kalian punya keduanya. Buktikan di medan tugas!', 'semangat', 'aula', 2, '2026-10-20 17:35:43.741059+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('2cc7d002-26a1-492a-b542-02cbf494944d', 'cedbd44c-77a0-472a-b340-2f1f58da25df', 'Peluk dari Ibu Dosen', 'Terima kasih sudah menjadi mahasiswa yang menyenangkan untuk dibimbing. Maaf bila tugas kami pernah membuat kalian begadang — itu tanda sayang kami pada masa depan kalian. Selamat bertugas, anak-anak hebat.', 'kasih', 'perpus', 2, '2026-10-20 17:35:43.743296+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('f4fa25ed-5208-46d7-8eec-fc1459e85fc4', '4ce466d1-439a-4b65-aa6a-4ff2d24c3761', 'Pesan dari Balik Kamera', 'Selama microteaching, saya banyak tertawa dalam hati melihat kalian gugup — dan menangis haru melihat kalian tumbuh. Sekarang giliran kalian membuat murid-murid tertawa dan menangis bangga. Semangat, Bapak-Ibu Guru!', 'lucu', 'parkir', 2, '2026-10-20 17:35:43.745493+00');
INSERT INTO public.ucapan (id, user_id, judul, isi, mood, zona, halaman_count, created_at) VALUES ('fd690115-1a32-4414-a4e5-8c931f65aee4', '8234fac7-a641-484c-8e8b-b8ffc6d5dfaa', 'Titik Balik', 'Menyaksikan kalian bertransformasi adalah hadiah terbesar bagi kami para dosen. Ingatlah: setiap murid yang kalian sentuh hari ini adalah perubahan bagi Indonesia sepuluh tahun lagi. Jaga amanah ini. Terima kasih, terima kasih, terima kasih.', 'syukur', 'lapangan', 2, '2026-10-20 17:35:43.747918+00');
